public display Name getPillarByDefaultDimension(AssetBook _this)
{
    Name        pillar;
    pillar  =   METHelper::getDimensionValue(_this.DefaultDimension,METConstants::pillar);
    return      pillar;
}

/// <summary>
/// MPJ_5583_Fixed asset transations
/// </summary>
/// <param name = "_this">
/// get AssetBook buffer
/// </param>
/// <returns>
/// return cost center dimension
/// </returns>
[SysClientCacheDataMethodAttribute (true)]
 static display Name getMETCostCenterByDefaultDimension(AssetBook   _this)
{
    Name                metCostCenter;
    metCostCenter   =   METHelper::getDimensionValue(_this.DefaultDimension,METConstants::costCenter);
    return              metCostCenter;
}

/// <summary>
/// MPJ_5583_Fixed asset transations
/// </summary>
/// <param name = "_this">
/// get buffer of the AssetBook
/// </param>
/// <returns>
/// retuen profit center dimension 
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
static display Name getMETProfitCenterByDefaultDimension(AssetBook   _this)
{
    Name                    metProfitcenter;
    metProfitcenter     =   METHelper::getDimensionValue(_this.DefaultDimension,METConstants::profitCentre);
    return                  metProfitcenter;
}
